    int n = 20;
    static String kind() { return "S"; }
    @Override String value() { return "sub:" + n; }
}
public class Main {
    public static void main(String[] args) {
        Base x = new Sub();
        System.out.print(x.n + ":");
        System.out.print(x.kind() + ":");
        System.out.print(x.value() + ":");
        System.out.print(((Sub) x).n + ":");
        System.out.print(Sub.kind());
    }
}

